import type { InstallContext } from '../products/types'

const ORIGIN_TOKEN = '__ORIGIN__'
const CHANNEL_TOKEN = '__CHANNEL__'
const VERSION_TOKEN = '__VERSION__'

export function renderBuildToolInstaller(context: InstallContext): string {
  return SCRIPT.replaceAll(ORIGIN_TOKEN, context.origin)
    .replaceAll(CHANNEL_TOKEN, context.channel)
    .replaceAll(VERSION_TOKEN, context.version ?? '')
}

const SCRIPT = `#!/usr/bin/env bash
#
# build-tool installer, generated by the get release API.
#
# Usage:
#   curl -fsSL __ORIGIN__/build-tool/install | bash
#   curl -fsSL "__ORIGIN__/build-tool/install?channel=stable" | bash
#   curl -fsSL __ORIGIN__/build-tool/install | bash -s <commit>
#
# Environment:
#   BUILD_TOOL_CHANNEL   release channel to install (default: __CHANNEL__)
#   BUILD_TOOL_BIN_DIR   directory for the binary (default: $HOME/.build/bin)

set -euo pipefail

TARGET_VERSION="\${1:-__VERSION__}"
CHANNEL="\${BUILD_TOOL_CHANNEL:-__CHANNEL__}"
PLATFORM="linux-x86_64"
API_BASE="__ORIGIN__"

case "$CHANNEL" in
    stable|beta|nightly) ;;
    *) echo "Invalid BUILD_TOOL_CHANNEL: '$CHANNEL' (expected stable, beta or nightly)" >&2; exit 1 ;;
esac

case "$(uname -s)/$(uname -m)" in
    Linux/x86_64|Linux/amd64) ;;
    *) echo "Unsupported platform: $(uname -s)/$(uname -m) (build-tool is Linux x86_64 only)" >&2; exit 1 ;;
esac

if command -v curl >/dev/null 2>&1; then
    DOWNLOADER="curl"
elif command -v wget >/dev/null 2>&1; then
    DOWNLOADER="wget"
else
    echo "Either curl or wget is required but neither is installed" >&2
    exit 1
fi

download_file() {
    local url="\${1:-}" output="\${2:-}"
    if [ "$DOWNLOADER" = "curl" ]; then
        if [ -n "$output" ]; then curl -fsSL -o "$output" "$url"; else curl -fsSL "$url"; fi
    else
        if [ -n "$output" ]; then wget -q -O "$output" "$url"; else wget -q -O - "$url"; fi
    fi
}

sha256_of() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "\${1:-}" 2>/dev/null | awk '{print $1}' || true
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "\${1:-}" 2>/dev/null | awk '{print $1}' || true
    else
        printf ''
    fi
}

manifest_url="\${API_BASE}/build-tool/v1/update?channel=\${CHANNEL}&platform=\${PLATFORM}&format=text"
if [ -n "$TARGET_VERSION" ]; then
    manifest_url="\${manifest_url}&target=\${TARGET_VERSION}"
fi

manifest="$(download_file "$manifest_url")" || {
    echo "Error: failed to fetch release information from \${manifest_url}" >&2
    exit 1
}

LATEST=""
KIND=""
URL=""
SHA=""
SIZE=""

while IFS= read -r line; do
    case "$line" in
        artifact=*) KIND="\${line#artifact=}"; URL=""; SHA=""; SIZE="" ;;
        url=*)      URL="\${line#url=}" ;;
        sha256=*)   SHA="\${line#sha256=}" ;;
        size=*)     SIZE="\${line#size=}" ;;
        latest=*)   LATEST="\${line#latest=}" ;;
    esac
    if [ "$KIND" = "binary" ] && [ -n "$URL" ] && [ -n "$SHA" ] && [ -n "$SIZE" ]; then
        break
    fi
done <<< "$manifest"

if [ -z "$LATEST" ] || [ -z "$URL" ] || [ -z "$SHA" ]; then
    echo "Error: the release API did not return a build-tool artifact" >&2
    exit 1
fi

BIN_DIR="\${BUILD_TOOL_BIN_DIR:-$HOME/.build/bin}"
mkdir -p "$BIN_DIR"
tmp="$(mktemp "\${BIN_DIR}/.build-tool.XXXXXX")"
trap 'rm -f "$tmp"' EXIT

download_file "$URL" "$tmp"
actual="$(sha256_of "$tmp")"
if [ -z "$actual" ] || [ "$actual" != "$SHA" ]; then
    echo "Error: checksum mismatch for build-tool \${LATEST}" >&2
    exit 1
fi

chmod +x "$tmp"
if ! "$tmp" --version </dev/null >/dev/null 2>&1; then
    echo "Error: downloaded build-tool failed to run" >&2
    exit 1
fi

mv -f "$tmp" "$BIN_DIR/build-tool"
trap - EXIT
echo "Installed build-tool \${LATEST} to $BIN_DIR/build-tool" >&2

case ":$PATH:" in
    *":$BIN_DIR:"*) ;;
    *) echo "Add $BIN_DIR to PATH to run build-tool directly." >&2 ;;
esac
`
